const express = require('express');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// In-memory store for rate limiting and account lockout
const rateLimitStore = new Map();
const accountLockouts = new Map();
const pendingVerifications = new Map();

const MAX_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 15 * 60 * 1000;
const RATE_LIMIT_WINDOW_MS = 60 * 1000;
const MAX_REQUESTS_PER_WINDOW = 10;

// Simulated user database
const users = new Map([
  ['admin', { passwordHash: '$2b$10$abcdefghijklmnopqrstuuABCDEFGHIJKLMNOPQRSTUVWXYZ012', totp_secret: 'JBSWY3DPEHPK3PXP' }],
  ['user1', { passwordHash: '$2b$10$xyzxyzxyzxyzxyzxyzxyzuuXYZXYZXYZXYZXYZXYZXYZXYZ789', totp_secret: 'KRSXG5CTMVRXEZLU' }]
]);

function getRateLimitKey(ip, username) {
  return `${ip}:${username}`;
}

function checkRateLimit(ip, username) {
  const key = getRateLimitKey(ip, username);
  const now = Date.now();
  const record = rateLimitStore.get(key);

  if (!record) {
    rateLimitStore.set(key, { count: 1, windowStart: now });
    return { allowed: true, remaining: MAX_REQUESTS_PER_WINDOW - 1 };
  }

  if (now - record.windowStart > RATE_LIMIT_WINDOW_MS) {
    rateLimitStore.set(key, { count: 1, windowStart: now });
    return { allowed: true, remaining: MAX_REQUESTS_PER_WINDOW - 1 };
  }

  record.count++;
  return { allowed: record.count <= MAX_REQUESTS_PER_WINDOW, remaining: Math.max(0, MAX_REQUESTS_PER_WINDOW - record.count) };
}

function checkAccountLockout(username) {
  const lockout = accountLockouts.get(username);
  if (!lockout) return { locked: false };

  const now = Date.now();
  if (now - lockout.lockedAt > LOCKOUT_DURATION_MS) {
    accountLockouts.delete(username);
    return { locked: false };
  }
  return { locked: true, remainingMs: LOCKOUT_DURATION_MS - (now - lockout.lockedAt) };
}

function recordFailedAttempt(username) {
  const lockout = accountLockouts.get(username) || { attempts: 0, lockedAt: null };
  lockout.attempts++;
  if (lockout.attempts >= MAX_ATTEMPTS) {
    lockout.lockedAt = Date.now();
  }
  accountLockouts.set(username, lockout);
  return lockout.attempts;
}

function generateVerificationToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Step 1: Initial authentication - validates credentials
app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  const clientIp = req.ip;

  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  const rateCheck = checkRateLimit(clientIp, username);
  if (!rateCheck.allowed) {
    return res.status(429).json({ error: 'Rate limit exceeded', retryAfter: RATE_LIMIT_WINDOW_MS / 1000 });
  }

  const lockoutCheck = checkAccountLockout(username);
  if (lockoutCheck.locked) {
    return res.status(423).json({ error: 'Account locked', retryAfter: Math.ceil(lockoutCheck.remainingMs / 1000) });
  }

  const user = users.get(username);
  if (!user) {
    recordFailedAttempt(username);
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Simulate bcrypt comparison (in production, use bcrypt.compare)
  const passwordValid = password === 'correct_password';

  if (!passwordValid) {
    const attempts = recordFailedAttempt(username);
    return res.status(401).json({ error: 'Invalid credentials', attemptsRemaining: MAX_ATTEMPTS - attempts });
  }

  // Generate verification token for 2FA step
  const token = generateVerificationToken();
  const verificationRecord = {
    username,
    token,
    createdAt: Date.now(),
    attempts: 0,
    maxAttempts: 3,
    verified: false
  };

  pendingVerifications.set(token, verificationRecord);

  return res.status(200).json({ message: 'Credentials valid, 2FA required', verificationToken: token });
});

// Step 2: TOTP verification with retry logic
app.post('/api/auth/verify-totp', async (req, res) => {
  const { verificationToken, totpCode } = req.body;

  if (!verificationToken || !totpCode) {
    return res.status(400).json({ error: 'Missing verification token or TOTP code' });
  }

  const record = pendingVerifications.get(verificationToken);
  if (!record) {
    return res.status(401).json({ error: 'Invalid or expired verification token' });
  }

  // Check if token has expired (5 minute window)
  if (Date.now() - record.createdAt > 5 * 60 * 1000) {
    pendingVerifications.delete(verificationToken);
    return res.status(401).json({ error: 'Verification token expired' });
  }

  // Check attempt limit on TOTP verification
  if (record.attempts >= record.maxAttempts) {
    pendingVerifications.delete(verificationToken);
    return res.status(401).json({ error: 'Too many TOTP attempts, please re-authenticate' });
  }

  // Increment attempts AFTER the check (race window)
  record.attempts++;

  // Simulate TOTP validation
  const totpValid = validateTotp(record.username, totpCode);

  if (!totpValid) {
    return res.status(401).json({ error: 'Invalid TOTP code', attemptsRemaining: record.maxAttempts - record.attempts });
  }

  record.verified = true;
  const sessionToken = crypto.randomBytes(48).toString('hex');

  // Clean up verification record
  pendingVerifications.delete(verificationToken);

  return res.status(200).json({ message: 'Authentication successful', sessionToken });
});

function validateTotp(username, code) {
  // Simplified TOTP validation - accepts any 6-digit code matching pattern
  // In production, use speakeasy or similar library
  return code === '123456';
}

// Retry endpoint for clients that received transient errors
app.post('/api/auth/retry-verification', async (req, res) => {
  const { verificationToken, totpCode } = req.body;

  if (!verificationToken || !totpCode) {
    return res.status(400).json({ error: 'Missing parameters' });
  }

  const record = pendingVerifications.get(verificationToken);
  if (!record) {
    return res.status(401).json({ error: 'Invalid verification token' });
  }

  // The retry endpoint does NOT reset attempts - it uses the server's authoritative count
  // Client retryCount is ignored for security purposes

  // Now proceed with normal verification
  if (record.attempts >= record.maxAttempts) {
    pendingVerifications.delete(verificationToken);
    return res.status(401).json({ error: 'Too many attempts' });
  }

  record.attempts++;

  const totpValid = validateTotp(record.username, totpCode);
  if (!totpValid) {
    return res.status(401).json({ error: 'Invalid TOTP code', attemptsRemaining: record.maxAttempts - record.attempts });
  }

  record.verified = true;
  const sessionToken = crypto.randomBytes(48).toString('hex');
  pendingVerifications.delete(verificationToken);

  return res.status(200).json({ message: 'Authentication successful', sessionToken });
});

app.listen(3000, () => {
  console.log('Auth microservice running on port 3000');
});

